import{_ as d,a0 as s,w as r,s as i,I as t,x as p,a1 as o,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"如何在 Ubuntu 中管理和使用 逻辑卷管理 LVM | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中管理和使用 逻辑卷管理 LVM | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中管理和使用 逻辑卷管理 LVM | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中管理和使用 逻辑卷管理 LVM | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150318 How to Manage and Use LVM (Logical Volume Management) in Ubuntu","title":"如何在 Ubuntu 中管理和使用 逻辑卷管理 LVM","tag":"201508","desc":""},"relativePath":"201508/20150318 How to Manage and Use LVM (Logical Volume Management) in Ubuntu.md","filePath":"[post].md"}'),g={name:"201508/20150318 How to Manage and Use LVM (Logical Volume Management) in Ubuntu.md"};function u(c,e,m,h,v,f){const a=s("Link");return r(),i("div",null,[e[20]||(e[20]=t("h1",{id:"如何在-ubuntu-中管理和使用-逻辑卷管理-lvm",tabindex:"-1"},[p("如何在 Ubuntu 中管理和使用 逻辑卷管理 LVM "),t("a",{class:"header-anchor",href:"#如何在-ubuntu-中管理和使用-逻辑卷管理-lvm","aria-label":"Permalink to “如何在 Ubuntu 中管理和使用 逻辑卷管理 LVM”"},"​")],-1)),e[21]||(e[21]=t("p",null,[t("img",{src:"http://cdn5.howtogeek.com/wp-content/uploads/2011/02/652x202xbanner-1.png.pagespeed.ic.VGSxDeVS9P.png",alt:""})],-1)),t("p",null,[e[1]||(e[1]=p("在我们之前的文章中，我们介绍了",-1)),o(a,{href:"https://linux.cn/article-5953-1.html"},{default:n(()=>[...e[0]||(e[0]=[p("什么是 LVM 以及能用 LVM 做什么",-1)])]),_:1}),e[2]||(e[2]=p("，今天我们会给你介绍一些 LVM 的主要管理工具，使得你在设置和扩展安装时更游刃有余。",-1))]),e[22]||(e[22]=l(`<p>正如之前所述，LVM 是介于你的操作系统和物理硬盘驱动器之间的抽象层。这意味着你的物理硬盘驱动器和分区不再依赖于他们所在的硬盘驱动和分区。而是你的操作系统所见的硬盘驱动和分区可以是由任意数目的独立硬盘汇集而成的或是一个软件磁盘阵列。</p><p>要管理 LVM，这里有很多可用的 GUI 工具，但要真正理解 LVM 配置发生的事情，最好要知道一些命令行工具。这当你在一个服务器或不提供 GUI 工具的发行版上管理 LVM 时尤为有用。</p><p>LVM 的大部分命令和彼此都非常相似。每个可用的命令都由以下其中之一开头：</p><ul><li>Physical Volume （物理卷） = pv</li><li>Volume Group （卷组）= vg</li><li>Logical Volume （逻辑卷）= lv</li></ul><p>物理卷命令用于在卷组中添加或删除硬盘驱动。卷组命令用于为你的逻辑卷操作更改显示的物理分区抽象集。逻辑卷命令会以分区形式显示卷组，使得你的操作系统能使用指定的空间。</p><h3 id="可下载的-lvm-备忘单" tabindex="-1">可下载的 LVM 备忘单 <a class="header-anchor" href="#可下载的-lvm-备忘单" aria-label="Permalink to “可下载的 LVM 备忘单”">​</a></h3><p>为了帮助你理解每个前缀可用的命令，我们制作了一个备忘单。我们会在该文章中介绍一些命令，但仍有很多你可用但没有介绍到的命令。</p><p>该列表中的所有命令都要以 root 身份运行，因为你更改的是会影响整个机器系统级设置。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/01/lvm-cheatsheet.png" alt=""></p><h3 id="如何查看当前-lvm-信息" tabindex="-1">如何查看当前 LVM 信息 <a class="header-anchor" href="#如何查看当前-lvm-信息" aria-label="Permalink to “如何查看当前 LVM 信息”">​</a></h3><p>你首先需要做的事情是检查你的 LVM 设置。s 和 display 命令可以和物理卷(pv)、卷组(vg)以及逻辑卷(lv)一起使用，是一个找出当前设置的好起点。</p><p>display 命令会格式化输出信息，因此比 s 命令更易于理解。对每个命令你会看到名称和 pv/vg 的路径，它还会给出空闲和已使用空间的信息。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/01/539x225xpvdisplay.png.pagespeed.ic.u2XV5LBTYa.png" alt=""></p><p>最重要的信息是 PV 名称和 VG 名称。用这两部分信息我们可以继续进行 LVM 设置。</p><h3 id="创建一个逻辑卷" tabindex="-1">创建一个逻辑卷 <a class="header-anchor" href="#创建一个逻辑卷" aria-label="Permalink to “创建一个逻辑卷”">​</a></h3><p>逻辑卷是你的操作系统在 LVM 中使用的分区。创建一个逻辑卷，首先需要拥有一个物理卷和卷组。下面是创建一个新的逻辑卷所需要的全部命令。</p><h4 id="创建物理卷" tabindex="-1">创建物理卷 <a class="header-anchor" href="#创建物理卷" aria-label="Permalink to “创建物理卷”">​</a></h4><p>我们会从一个全新的没有任何分区和信息的硬盘开始。首先找出你将要使用的磁盘。(/dev/sda, sdb, 等)</p><blockquote><p>注意：记住所有的命令都要以 root 身份运行或者在命令前面添加 &#39;sudo&#39; 。</p></blockquote><pre><code>fdisk -l
</code></pre><p>如果之前你的硬盘从未格式化或分区过，在 fdisk 的输出中你很可能看到类似下面的信息。这完全正常，因为我们会在下面的步骤中创建需要的分区。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/fdisk.png.pagespeed.ce.AmAEsxm-7Q.png" alt=""></p><p>我们的新磁盘位置是 /dev/sdb，让我们用 fdisk 命令在磁盘上创建一个新的分区。</p>`,23)),t("p",null,[e[4]||(e[4]=p("这里有大量能创建新分区的 GUI 工具，包括 ",-1)),o(a,{href:"http://www.howtogeek.com/howto/17001/how-to-format-a-usb-drive-in-ubuntu-using-gparted/"},{default:n(()=>[...e[3]||(e[3]=[p("Gparted",-1)])]),_:1}),e[5]||(e[5]=p("，但由于我们已经打开了终端，我们将使用 fdisk 命令创建需要的分区。",-1))]),e[23]||(e[23]=l(`<p>在终端中输入以下命令：</p><pre><code>fdisk /dev/sdb
</code></pre><p>这会使你进入到一个特殊的 fdisk 提示符中。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/627x145xfdisk00.png.pagespeed.ic.I7S8bjoXQG.png" alt=""></p><p>以指定的顺序输入命令创建一个使用新硬盘 100% 空间的主分区并为 LVM 做好了准备。如果你需要更改分区的大小或想要多个分区，我建议使用 GParted 或自己了解一下关于 fdisk 命令的使用。</p><p><strong>警告：下面的步骤会格式化你的硬盘驱动。确保在进行下面步骤之前你的硬盘驱动中没有任何有用的信息。</strong></p><ul><li>n = 创建新分区</li><li>p = 创建主分区</li><li>1 = 成为磁盘上的首个分区</li></ul><p>输入 enter 键两次以接受默认的第一个和最后一个柱面。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/562x216xfdisk01.png.pagespeed.ic.DsSZ38kWcA.png" alt=""></p><p>用下面的命令准备 LVM 所使用的分区。</p><ul><li>t = 更改分区类型</li><li>8e = 更改为 LVM 分区类型</li></ul><p>核实并将信息写入硬盘。</p><ul><li>p = 查看分区设置使得在写入更改到磁盘之前可以回看</li><li>w = 写入更改到磁盘</li></ul><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/560x339xfdisk03.png.pagespeed.ic.FC8foICZsb.png" alt=""></p><p>运行这些命令之后，会退出 fdisk 提示符并返回到终端的 bash 提示符中。</p><p>输入 pvcreate /dev/sdb1 在刚创建的分区上新建一个 LVM 物理卷。</p><p>你也许会问为什么我们不用一个文件系统格式化分区，不用担心，该步骤在后面。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/pvcreate.png.pagespeed.ce.W7VAr-ig3t.png" alt=""></p><h4 id="创建卷组" tabindex="-1">创建卷组 <a class="header-anchor" href="#创建卷组" aria-label="Permalink to “创建卷组”">​</a></h4><p>现在我们有了一个指定的分区和创建好的物理卷，我们需要创建一个卷组。很幸运这只需要一个命令。</p><pre><code>vgcreate vgpool /dev/sdb1
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/vgcreate.png.pagespeed.ce.fVLzSmPZou.png" alt=""></p><p>vgpool 是新创建的卷组的名称。你可以使用任何你喜欢的名称，但建议标签以 vg 开头，以便后面你使用它时能意识到这是一个卷组。</p><h4 id="创建逻辑卷" tabindex="-1">创建逻辑卷 <a class="header-anchor" href="#创建逻辑卷" aria-label="Permalink to “创建逻辑卷”">​</a></h4><p>创建 LVM 将使用的逻辑卷：</p><pre><code>lvcreate -L 3G -n lvstuff vgpool
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/lvcreate.png.pagespeed.ce.vupLB-LJEW.png" alt=""></p><p>-L 命令指定逻辑卷的大小，在该情况中是 3 GB，-n 命令指定卷的名称。 指定 vgpool 以便 lvcreate 命令知道从什么卷获取空间。</p><h4 id="格式化并挂载逻辑卷" tabindex="-1">格式化并挂载逻辑卷 <a class="header-anchor" href="#格式化并挂载逻辑卷" aria-label="Permalink to “格式化并挂载逻辑卷”">​</a></h4>`,29)),t("p",null,[e[7]||(e[7]=p("最后一步是用一个文件系统格式化新的逻辑卷。如果你需要选择一个 Linux 文件系统的帮助，请阅读 ",-1)),o(a,{href:"http://www.howtogeek.com/howto/33552/htg-explains-which-linux-file-system-should-you-choose/"},{default:n(()=>[...e[6]||(e[6]=[p("如果根据需要选取最合适的文件系统",-1)])]),_:1}),e[8]||(e[8]=p("。",-1))]),e[24]||(e[24]=l(`<pre><code>mkfs -t ext3 /dev/vgpool/lvstuff
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/571x424xmkfs.png.pagespeed.ic.ERMan1Mz0P.png" alt=""></p><p>创建挂载点并将卷挂载到你可以使用的地方。</p><pre><code>mkdir /mnt/stuff
mount -t ext3 /dev/vgpool/lvstuff /mnt/stuff
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/510x69xmount.png.pagespeed.ic.k0i1tvqgcV.png" alt=""></p><h4 id="重新设置逻辑卷大小" tabindex="-1">重新设置逻辑卷大小 <a class="header-anchor" href="#重新设置逻辑卷大小" aria-label="Permalink to “重新设置逻辑卷大小”">​</a></h4><p>逻辑卷的一个好处是你能使你的存储物理地变大或变小，而不需要移动所有东西到一个更大的硬盘。另外，你可以添加新的硬盘并同时扩展你的卷组。或者如果你有一个不使用的硬盘，你可以从卷组中移除它使得逻辑卷变小。</p><p>这里有三个用于使物理卷、卷组和逻辑卷变大或变小的基础工具。</p><p>注意：这些命令中的每个都要以 pv、vg 或 lv 开头，取决于你的工作对象。</p><ul><li>resize – 能压缩或扩展物理卷和逻辑卷，但卷组不能</li><li>extend – 能使卷组和逻辑卷变大但不能变小</li><li>reduce – 能使卷组和逻辑卷变小但不能变大</li></ul><p>让我们来看一个如何向刚创建的逻辑卷 &quot;lvstuff&quot; 添加新硬盘驱动的例子。</p><h4 id="安装并格式化新硬盘驱动" tabindex="-1">安装并格式化新硬盘驱动 <a class="header-anchor" href="#安装并格式化新硬盘驱动" aria-label="Permalink to “安装并格式化新硬盘驱动”">​</a></h4><p>按照上面创建新分区并更改分区类型为 LVM(8e) 的步骤安装一个新硬盘驱动。然后用 pvcreate 命令创建一个 LVM 能识别的物理卷。</p><h4 id="添加新硬盘到卷组" tabindex="-1">添加新硬盘到卷组 <a class="header-anchor" href="#添加新硬盘到卷组" aria-label="Permalink to “添加新硬盘到卷组”">​</a></h4><p>要添加新的硬盘到一个卷组，你只需要知道你的新分区，在我们的例子中是 /dev/sdc1，以及想要添加到的卷组的名称。</p><p>这会添加新物理卷到已存在的卷组中。</p><pre><code>vgextend vgpool /dev/sdc1
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/vgextend.png.pagespeed.ce.atRPT1yg5f.png" alt=""></p><h4 id="扩展逻辑卷" tabindex="-1">扩展逻辑卷 <a class="header-anchor" href="#扩展逻辑卷" aria-label="Permalink to “扩展逻辑卷”">​</a></h4><p>调整逻辑卷的大小，我们需要指出的是通过大小而不是设备来扩展。在我们的例子中，我们会添加一个 8GB 的硬盘驱动到我们的 3GB vgpool。我们可以用 lvextend 或 lvresize 命令使该空间可用。</p><pre><code>lvextend -L8G /dev/vgpool/lvstuff
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/lvextend1.png.pagespeed.ce.6scXbQVUTT.png" alt=""></p><p>当这个命令工作的时候你会发现它实际上重新设置逻辑卷大小为 8GB 而不是我们期望的将 8GB 添加到已存在的卷上。要添加剩余的可用 3GB 你需要用下面的命令。</p><pre><code>lvextend -L+3G /dev/vgpool/lvstuff
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/430x85xlvextend2.png.pagespeed.ic.7aBiTBrW03.png" alt=""></p><p>现在我们的逻辑卷已经是 11GB 大小了。</p><h4 id="扩展文件系统" tabindex="-1">扩展文件系统 <a class="header-anchor" href="#扩展文件系统" aria-label="Permalink to “扩展文件系统”">​</a></h4><p>逻辑卷是 11GB 大小但是上面的文件系统仍然只有 3GB。要使文件系统使用整个的 11GB 可用空间你需要用 resize2fs 命令。你只需要指定 resize2fs 到 11GB 逻辑卷它就会帮你完成其余的工作。</p><pre><code>resize2fs /dev/vgpool/lvstuff
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/650x150xresize2fs.png.pagespeed.ic.Mx74EdMuk_.png" alt=""></p><p><strong>注意：如果你使用除 ext3/4 之外的文件系统，请查看调整你的文件系统大小的工具。</strong></p><h4 id="压缩逻辑卷" tabindex="-1">压缩逻辑卷 <a class="header-anchor" href="#压缩逻辑卷" aria-label="Permalink to “压缩逻辑卷”">​</a></h4><p>如果你想从卷组中移除一个硬盘驱动你可以按照上面的步骤反向操作，并用 lvreduce 或 vgreduce 命令代替。</p><ol><li>调整文件系统大小 (调整之前确保已经移动文件到硬盘驱动安全的地方)</li><li>减小逻辑卷 (除了 + 可以扩展大小，你也可以用 - 压缩大小)</li><li>用 vgreduce 从卷组中移除硬盘</li></ol><h4 id="备份逻辑卷" tabindex="-1">备份逻辑卷 <a class="header-anchor" href="#备份逻辑卷" aria-label="Permalink to “备份逻辑卷”">​</a></h4><p>快照是一些新的高级文件系统提供的功能，但是 ext3/4 文件系统并没有快照的功能。LVM 快照最棒的是你的文件系统永不掉线，你可以拥有你想要的任何大小而不需要额外的硬盘空间。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/652x202xbanner-2.png.pagespeed.ic.VtOUuqYX1W.png" alt=""></p><p>LVM 获取快照的时候，会有一张和逻辑卷完全相同的“照片”，该“照片”可以用于在不同的硬盘上进行备份。生成一个备份的时候，任何需要添加到逻辑卷的新信息会如往常一样写入磁盘，但会跟踪更改使得原始快照永远不会损毁。</p><p>要创建一个快照，我们需要创建拥有足够空闲空间的逻辑卷，用于保存我们备份的时候会写入该逻辑卷的任何新信息。如果驱动并不是经常写入，你可以使用很小的一个存储空间。备份完成的时候我们只需要移除临时逻辑卷，原始逻辑卷会和往常一样。</p><h4 id="创建新快照" tabindex="-1">创建新快照 <a class="header-anchor" href="#创建新快照" aria-label="Permalink to “创建新快照”">​</a></h4><p>创建 lvstuff 的快照，用带 -s 标记的 lvcreate 命令。</p><pre><code>lvcreate -L512M -s -n lvstuffbackup /dev/vgpool/lvstuff
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/597x68xlvcreate-snapshot.png.pagespeed.ic.Rw2ivtcpPg.png" alt=""></p><p>这里我们创建了一个只有 512MB 的逻辑卷，因为该硬盘实际上并不会使用。512MB 的空间会保存备份时产生的任何新数据。</p><h4 id="挂载新快照" tabindex="-1">挂载新快照 <a class="header-anchor" href="#挂载新快照" aria-label="Permalink to “挂载新快照”">​</a></h4><p>和之前一样，我们需要创建一个挂载点并挂载新快照，然后才能从中复制文件。</p><pre><code>mkdir /mnt/lvstuffbackup
mount /dev/vgpool/lvstuffbackup /mnt/lvstuffbackup
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/565x68xmount-snapshot.png.pagespeed.ic.pVMkhK1o4x.png" alt=""></p><h4 id="复制快照和删除逻辑卷" tabindex="-1">复制快照和删除逻辑卷 <a class="header-anchor" href="#复制快照和删除逻辑卷" aria-label="Permalink to “复制快照和删除逻辑卷”">​</a></h4><p>你剩下需要做的是从 /mnt/lvstuffbackup/ 中复制所有文件到一个外部的硬盘或者打包所有文件到一个文件。</p><p><strong>注意：tar -c 会创建一个归档文件，-f 要指出归档文件的名称和路径。要获取 tar 命令的帮助信息，可以在终端中输入 man tar。</strong></p><pre><code>tar -cf /home/rothgar/Backup/lvstuff-ss /mnt/lvstuffbackup/
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/627x67xsnapshot-backup.png.pagespeed.ic.tw-2AK_lfZ.png" alt=""></p><p>记住备份时候写到 lvstuff 的所有文件都会在我们之前创建的临时逻辑卷中被跟踪。确保备份的时候你有足够的空闲空间。</p><p>备份完成后，卸载卷并移除临时快照。</p><pre><code>umount /mnt/lvstuffbackup
lvremove /dev/vgpool/lvstuffbackup/
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/630x102xlvremove.png.pagespeed.ic.yBWk47X6lF.png" alt=""></p><h4 id="删除逻辑卷" tabindex="-1">删除逻辑卷 <a class="header-anchor" href="#删除逻辑卷" aria-label="Permalink to “删除逻辑卷”">​</a></h4><p>要删除一个逻辑卷，你首先需要确保卷已经卸载，然后你可以用 lvremove 命令删除它。逻辑卷删除后你可以移除卷组，卷组删除后你可以删除物理卷。</p><p>这是所有移除我们创建的卷和组的命令。</p><pre><code>umount /mnt/lvstuff
lvremove /dev/vgpool/lvstuff
vgremove vgpool
pvremove /dev/sdb1 /dev/sdc1
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2011/02/580x185xdelete-lvm.png.pagespeed.ic.3zJTo0Zu9k.png" alt=""></p><p>这些已经囊括了关于 LVM 你需要了解的大部分知识。如果你有任何关于这些讨论的经验，请在下面的评论框中和大家分享。</p><hr>`,64)),t("p",null,[e[10]||(e[10]=p("via: ",-1)),o(a,{href:"http://www.howtogeek.com/howto/40702/how-to-manage-and-use-lvm-logical-volume-management-in-ubuntu/"},{default:n(()=>[...e[9]||(e[9]=[p("http://www.howtogeek.com/howto/40702/how-to-manage-and-use-lvm-logical-volume-management-in-ubuntu/",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=p("译者：",-1)),o(a,{href:"https://github.com/ictlyh"},{default:n(()=>[...e[11]||(e[11]=[p("ictlyh",-1)])]),_:1}),e[14]||(e[14]=p(" 校对：",-1)),o(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[12]||(e[12]=[p("wxy",-1)])]),_:1})]),t("p",null,[e[17]||(e[17]=p("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[15]||(e[15]=[p("LCTT",-1)])]),_:1}),e[18]||(e[18]=p(" 原创翻译，",-1)),o(a,{href:"http://linux.cn/"},{default:n(()=>[...e[16]||(e[16]=[p("Linux中国",-1)])]),_:1}),e[19]||(e[19]=p(" 荣誉推出",-1))])])}const w=d(g,[["render",u]]);export{b as __pageData,w as default};
